const neuroPairs=[{"trans":"«Esto vale doscientos mil, pero te lo dejo en ochenta»","func":"Anclaje: el primer número fija el terreno","opts":["Anclaje: el primer número fija el terreno","Halo: el prestigio de quien lo dice","Disponibilidad: lo que más se recuerda","Confirmación: solo lo que encaja"]},{"trans":"«Si no firmas esta semana, el presupuesto se cierra»","func":"Aversión a la pérdida: duele más perderlo que ganarlo","opts":["Aversión a la pérdida: duele más perderlo que ganarlo","Costo hundido: lo que ya se invirtió","Superviviente: solo se ven los que ganaron","Anclaje: la primera cifra"]},{"trans":"«Es una institución muy seria, seguro que el convenio conviene»","func":"Halo: lo bueno en una cosa se contagia a todas","opts":["Halo: lo bueno en una cosa se contagia a todas","Disponibilidad: el caso más ruidoso","Confirmación: preguntar a los propios","Exceso de confianza: estimar de más"]},{"trans":"«Este canal explotó con vídeos cortos, hagamos lo mismo»","func":"Superviviente: no se ve a los que hicieron igual y fracasaron","opts":["Superviviente: no se ve a los que hicieron igual y fracasaron","Anclaje: la cifra de las vistas","Halo: el nombre del canal","Costo hundido: lo ya publicado"]},{"trans":"«Llevamos setecientas horas, no vamos a tirarlas ahora»","func":"Costo hundido: lo gastado no vuelve y no es un argumento","opts":["Costo hundido: lo gastado no vuelve y no es un argumento","Aversión a la pérdida: el plazo que vence","Confirmación: el dato que encaja","Disponibilidad: lo más reciente"]}];
