// Widget 4: Problema real → pieza que lo resuelve
const enfermedadData=[{"disease":"Se siguió un año más con algo que ya no servía","characteristic":"Costo hundido: se contaron las horas gastadas como razón","opts":["Costo hundido: se contaron las horas gastadas como razón","Anclaje: el primer número era alto","Halo: el proveedor tenía buen nombre","Disponibilidad: hubo una queja fuerte"]},{"disease":"Se cerró el trato en la cifra que propuso el otro","characteristic":"Anclaje: nunca se calculó el número propio antes","opts":["Anclaje: nunca se calculó el número propio antes","Confirmación: se preguntó a los propios","Superviviente: se copió a quien ganó","Exceso de confianza: se estimó de más"]},{"disease":"Todos los que opinaron dijeron que iba muy bien, y el uso bajaba","characteristic":"Confirmación: solo se le preguntó a quien ya lo usaba","opts":["Confirmación: solo se le preguntó a quien ya lo usaba","Halo: los que opinaron eran conocidos","Anclaje: la primera opinión pesó de más","Costo hundido: ya se había publicado"]},{"disease":"Se rediseñó el proyecto entero por un solo comentario","characteristic":"Disponibilidad: el caso ruidoso se confundió con el frecuente","opts":["Disponibilidad: el caso ruidoso se confundió con el frecuente","Aversión a la pérdida: se temía perder a esa persona","Halo: quien se quejó tenía prestigio","Anclaje: la queja fue la primera"]},{"disease":"Se firmó un convenio que leído con calma no convenía","characteristic":"Halo: el prestigio de la institución tapó las condiciones","opts":["Halo: el prestigio de la institución tapó las condiciones","Superviviente: otros lo habían firmado","Costo hundido: ya se habían hecho reuniones","Disponibilidad: se recordaba un caso bueno"]},{"disease":"La ruta que iba a estar en un mes tardó cinco","characteristic":"Exceso de confianza: se estimó sin mirar el historial propio","opts":["Exceso de confianza: se estimó sin mirar el historial propio","Confirmación: se buscó quien dijera que sí","Anclaje: alguien dijo un mes primero","Aversión a la pérdida: no se quiso soltar"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

