const evalMCBank=[{"q":"¿Qué es un sesgo?","o":["a) Un atajo del cerebro que ahorra energía","b) Una opinión mal formada","c) Una técnica de manipulación","d) Un error de cálculo"],"a":0},{"q":"«Vale 200.000, te lo dejo en 80.000» usa…","o":["a) Halo","b) Anclaje","c) Disponibilidad","d) Costo hundido"],"a":1},{"q":"El antídoto del costo hundido es…","o":["a) Calcular lo invertido","b) Esperar a recuperarlo","c) Pedir otra opinión","d) Preguntarse qué se elegiría empezando hoy"],"a":3},{"q":"Preguntarle solo a quien ya usa el proyecto es…","o":["a) Confirmación","b) Anclaje","c) Halo","d) Superviviente"],"a":0},{"q":"¿Por qué funciona un plazo que vence el viernes?","o":["a) Por el sesgo del halo","b) Por la aversión a la pérdida","c) Por el anclaje","d) Por la disponibilidad"],"a":1},{"q":"Copiar al canal del millón de vistas es sesgo del…","o":["a) Halo","b) Anclaje","c) Costo hundido","d) Superviviente"],"a":3},{"q":"Una queja ruidosa contra cuarenta usos callados es…","o":["a) Confirmación","b) Disponibilidad","c) Exceso de confianza","d) Anclaje"],"a":1},{"q":"Que una institución seria proponga algo malo y suene bien es…","o":["a) Halo","b) Anclaje","c) Superviviente","d) Disponibilidad"],"a":0},{"q":"¿Cuál es la diferencia entre sesgo y palanca?","o":["a) El sesgo viene de dentro, la palanca de fuera","b) La palanca es involuntaria","c) El sesgo es más grave","d) No hay diferencia real"],"a":0},{"q":"¿Qué pregunta desactiva el anclaje?","o":["a) ¿Cuánto es lo mínimo?","b) ¿Puedo pensarlo?","c) ¿De dónde salió esa cifra?","d) ¿Quién más lo aceptó?"],"a":2},{"q":"¿Cuándo NO se decide algo que importa?","o":["a) Con la hoja de las cinco preguntas","b) Por la mañana y con tiempo","c) Cansado y con alguien esperando","d) Después de escribir el número propio"],"a":2},{"q":"Calcular que seis etapas salen en un mes es…","o":["a) Disponibilidad","b) Confirmación","c) Exceso de confianza","d) Halo"],"a":2},{"q":"¿Qué se hace si el otro ya puso el primer número?","o":["a) Negociar a partir de ahí","b) Aceptar si el descuento es bueno","c) Pedir tiempo y volver con la mitad","d) Decir que ese número es suyo y sacar el propio"],"a":3},{"q":"La prueba de que la etapa está aprendida es…","o":["a) Saber los ocho nombres","b) Haberse cazado a uno mismo y haberlo apuntado","c) Reconocer los sesgos ajenos","d) Haber leído la ficha"],"a":1},{"q":"¿Qué significa decidir en frío?","o":["a) Decidir rápido para no dudar","b) Decidir sin sentimientos","c) Separar el momento de escuchar del de decidir","d) Decidir siempre que no"],"a":2}];
