function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un inversionista abre la reunión así: «esto vale 200.000 lempiras, y te doy 80.000 por el 40%». Nadie ha calculado antes cuánto vale el proyecto."},{"txt":"Llevas setecientas horas en el motor de misiones y aparece una plataforma que hace el 80% de lo mismo por 30 dólares al mes."},{"txt":"Se propone copiar la táctica de un canal educativo que llegó al millón de vistas: vídeos cortos, títulos llamativos y publicar a diario."},{"txt":"Para saber si el proyecto va bien, se le pregunta a las maestras que usan M.E.T.A.S todas las semanas."},{"txt":"Una institución ofrece un convenio y avisa de que el presupuesto se cierra el viernes, así que hay que contestar antes."},{"txt":"Una maestra se queja fuerte de que una misión no le sirvió. Ese mismo mes hubo cuarenta usos sin ningún comentario."},{"txt":"Una institución muy conocida propone un convenio cuyas condiciones, leídas con calma, no convienen al proyecto."},{"txt":"Al planear una ruta nueva se calcula que las seis etapas estarán construidas en cuatro semanas."}];
const critCaseQuestions=["1. ¿Qué sesgo está trabajando por debajo de esta decisión?","2. ¿Qué información falta en la mesa, y quién la tiene?","3. Escribe en 3-4 frases la pregunta que harías antes de contestar.","4. ¿Qué decidirías si empezaras hoy desde cero y sin plazo?"];
const critCaseGuides=["Nombrar el sesgo es la mitad del trabajo: anclaje si hay una cifra ajena, costo hundido si se cuenta lo ya gastado, confirmación si solo se consultó a los propios, halo si pesa el nombre de quien propone.","Casi siempre falta el dato incómodo: los que probaron y fracasaron, los que dejaron de usarlo, el número real sobre el total, o el cálculo propio que nadie hizo antes de la reunión.","La pregunta se escribe, no se improvisa. Las cinco de la hoja cubren casi todo: de dónde salió el número, qué dato me haría cambiar, si empezaría hoy, cuántos casos sobre cuántos, y si lo aceptaría sin fecha.","Quitar el plazo y lo invertido deja ver la decisión desnuda. Si sin presión la respuesta cambia, entonces la presión estaba decidiendo, no los hechos."];

const critErrorBank=[{"txt":"\"Bajaron de doscientos mil a sesenta mil, así que salimos ganando\".","g1":"Los doscientos mil no salieron de ningún cálculo: los puso quien compra, y todo el regateo ocurrió dentro de su terreno.","g2":"El número propio se calcula en casa antes de la reunión. Sin él, el descuento se siente victoria y se cierra donde el otro quería."},{"txt":"\"Llevamos setecientas horas, sería tirar todo eso a la basura\".","g1":"Las horas ya se gastaron y no vuelven, se decida lo que se decida. Contarlas solo añade horas nuevas a las perdidas.","g2":"La pregunta es qué se elegiría empezando hoy desde cero. Puede que la respuesta sea seguir, pero por control y por funcionar sin internet, no por lo gastado."},{"txt":"\"Todas las maestras a las que preguntamos dicen que va muy bien\".","g1":"Se preguntó donde solo podía salir un sí. Las que abrieron una vez y no volvieron tienen la respuesta útil y nadie las llamó.","g2":"Se anota qué dato haría cambiar de opinión y se sale a buscarlo: tres conversaciones con quien lo dejó valen más que veinte felicitaciones."},{"txt":"\"Hay que cambiarlo todo, porque una maestra se quejó muchísimo\".","g1":"Lo ruidoso no es lo frecuente: una queja vívida pesa más que cuarenta usos callados, y el proyecto termina cambiando por el caso más sonoro.","g2":"La queja se atiende siempre, porque puede tener razón. Lo que no se hace es rediseñar sin mirar cuántos casos hay sobre cuántos en total."},{"txt":"\"Es una institución muy seria, el convenio seguro que conviene\".","g1":"El prestigio dice cómo son en lo suyo, no si este trato concreto conviene. Lo bueno en una cosa se contagia a todas sin motivo.","g2":"Se lee la propuesta con el nombre tapado y se pregunta si se aceptaría igual viniendo de un desconocido."},{"txt":"\"Las seis etapas salen en un mes, ya le agarré el ritmo\".","g1":"Se está estimando con el mejor día imaginable: sin cortes de luz, sin fichas que rehacer, sin domingos que se van en otra cosa.","g2":"Se mira el historial propio: si la etapa anterior tomó tres tandas, esta va a tomar tres. El antídoto no es el pesimismo, es el dato."}];

const critDecisionBank=["Un inversionista abre con «vale 200.000, te doy 80.000 por el 40%»: ¿qué se hace antes de responder cualquier cifra?","Aparece una plataforma que hace el 80% del motor por 30 dólares al mes: ¿cómo se decide sin contar las setecientas horas?","Se propone copiar al canal del millón de vistas: ¿qué hay que averiguar antes de imitar la táctica?","Todas las maestras consultadas dicen que va bien y el uso baja: ¿a quién hay que llamar?","El convenio se cae si no se firma el viernes: ¿qué pregunta se contesta primero?","Una queja muy fuerte contra cuarenta usos callados: ¿qué se mira antes de cambiar nada?","Una institución conocida propone condiciones que no convienen: ¿cómo se lee la propuesta?","Se calcula que la ruta nueva sale en un mes: ¿de dónde se saca la estimación buena?"];
const critDecisionGuide="La decisión correcta sigue los principios de la casa: se identifica quién firma, quién traba y quién paga antes de responder; se empieza pequeño y reversible; nunca se compromete a terceros que no firmaron; la autoría y el uso se acuerdan antes de entregar, no después; y todo queda por escrito con la institución y no con la persona. Cuando la oferta es grande y urgente, esa combinación es justamente la señal para tomarse los días que hagan falta y responder con una condición concreta.";

const critCompareBank=[{"a":"Llegar a la reunión con el valor del proyecto ya calculado y escrito.","b":"Llegar a escuchar la oferta y ver qué cifra proponen.","ga":"Caso A: el terreno es propio y el número del otro se puede nombrar como ajeno.","gb":"Caso B: el primer número que se escuche va a decidir toda la conversación, y el regateo va a parecer una victoria."},{"a":"Hablar con tres maestras que dejaron de usar M.E.T.A.S.","b":"Hablar con las tres que lo usan todas las semanas.","ga":"Caso A: ahí está el dato que puede cambiar la decisión, aunque la conversación incomode.","gb":"Caso B: se busca información donde solo puede salir un sí, y se confunde con una medición."},{"a":"Estimar la ruta nueva mirando cuánto tardó la anterior.","b":"Estimar la ruta nueva pensando en un mes de trabajo seguido.","ga":"Caso A: el historial propio es el único dato honesto que hay sobre uno mismo.","gb":"Caso B: se estima con el mejor día imaginable y después se explica el retraso con imprevistos que siempre ocurren."},{"a":"Contestar «lo veo y te digo mañana» y responder la hoja de las cinco.","b":"Contestar en la reunión porque el presupuesto se cierra el viernes.","ga":"Caso A: si el plazo era real, un día no lo rompe; si lo rompe, dependía de que no lo pensaras.","gb":"Caso B: se decide con aversión a la pérdida y con alguien esperando, que es la peor combinación posible."}];

const critCauseBank=[{"cause":"Se entra a negociar sin el número propio calculado.","guide":"La primera cifra del otro fija el terreno y todo lo demás es regateo dentro de su marco. El descuento se sentirá como victoria."},{"cause":"Se cuentan las horas invertidas como razón para seguir.","guide":"Es costo hundido: lo gastado no vuelve y meterlo en la balanza solo añade pérdidas nuevas. La pregunta correcta es qué se elegiría hoy desde cero."},{"cause":"Se consulta solo a quien ya usa el proyecto.","guide":"Sesgo de confirmación: se busca donde solo puede salir un sí, y el dato útil está en quien dejó de usarlo."},{"cause":"Se rediseña por el comentario más ruidoso.","guide":"Disponibilidad: lo vívido se confunde con lo frecuente. Antes de cambiar, cuántos casos hay sobre cuántos en total."},{"cause":"Se acepta un plazo corto sin preguntarse si es real.","guide":"Aversión a la pérdida: no se está aceptando la oferta, se está huyendo de perderla. Un día de espera lo revela."},{"cause":"Se estima el trabajo sin mirar cuánto tardó lo anterior.","guide":"Exceso de confianza: se planifica con el mejor día imaginable, y después el retraso se explica con imprevistos que siempre ocurren."}];
const critEffectBank=[{"effect":"La reunión empezó con el número propio sobre la mesa.","guide":"El anclaje quedó desactivado antes de existir: quien pone la primera cifra fija el terreno, y esta vez fue el que construyó."},{"effect":"Se soltó una función en la que había mucho trabajo metido.","guide":"Se decidió mirando qué convenía de aquí en adelante y no lo gastado. Eso es exactamente vencer el costo hundido."},{"effect":"Tres conversaciones incómodas cambiaron el rumbo del proyecto.","guide":"Se fue a buscar el dato que podía contradecir, en vez del que iba a confirmar. Es la hora mejor invertida del mes."},{"effect":"Se atendió la queja sin rediseñar el proyecto entero.","guide":"Se miró cuántos casos había sobre el total. La queja tenía parte de razón y aun así no era la regla."},{"effect":"Se pidió un día para contestar y el plazo resultó flexible.","guide":"Casi todos los plazos lo son. El que no lo es, casi siempre dependía de que no lo pensaras."},{"effect":"La ruta se planificó en tres tandas y salió en tres tandas.","guide":"Se estimó con el historial propio en la mano. El antídoto del exceso de confianza es un dato, no una actitud."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 La sala de espejos · Forma ${cf} · Sesgos, los atajos que deciden por ti · Ruta de la Persuasión`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Sesgos, los atajos que deciden por ti, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La sala de espejos: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Sesgos, los atajos que deciden por ti, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La sala de espejos Sesgos, los atajos que deciden por ti · Ruta de la Persuasión · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La sala de espejos · Sesgos, los atajos que deciden por ti · Ruta de la Persuasión · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La sala de espejos · Sesgos, los atajos que deciden por ti · Ruta de la Persuasión · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"⚓","label":"Anclaje","text":"El <strong>primer número</strong> fija el terreno. <strong>Gatillo:</strong> alguien dice una cifra antes que tú. <strong>Por dentro:</strong> todo lo demás se juzga como distancia a ese número. <strong>Antídoto:</strong> «¿de dónde salió esa cifra?», y sacar la propia, calculada antes."},{"y":"2","icon":"🔍","label":"Confirmación","text":"Se ve <strong>lo que encaja</strong> con lo que ya se creía. <strong>Gatillo:</strong> tener ya una opinión. <strong>Por dentro:</strong> se busca donde solo puede salir un sí. <strong>Antídoto:</strong> «¿qué dato me haría cambiar de opinión?», y salir a buscarlo."},{"y":"3","icon":"😰","label":"Aversión a la pérdida","text":"Perder duele el <strong>doble</strong> de lo que alegra ganar. <strong>Gatillo:</strong> un plazo o una amenaza de quedarse sin algo. <strong>Por dentro:</strong> se decide huyendo, no eligiendo. <strong>Antídoto:</strong> «si no tuviera fecha, ¿lo aceptaría igual?»."},{"y":"4","icon":"📢","label":"Disponibilidad","text":"Lo que se <strong>recuerda con fuerza</strong> parece más probable. <strong>Gatillo:</strong> un caso vívido o reciente. <strong>Por dentro:</strong> el ruido se confunde con la frecuencia. <strong>Antídoto:</strong> «¿cuántos casos hay, sobre cuántos en total?»."},{"y":"5","icon":"✨","label":"Halo","text":"Bueno en una cosa, <strong>bueno en todas</strong>. <strong>Gatillo:</strong> un nombre con prestigio. <strong>Por dentro:</strong> la reputación tapa las condiciones concretas. <strong>Antídoto:</strong> leer la propuesta con el nombre tapado."},{"y":"6","icon":"🕳️","label":"Costo hundido","text":"Seguir por <strong>lo ya invertido</strong>. <strong>Gatillo:</strong> mucho tiempo o dinero metido. <strong>Por dentro:</strong> se añaden pérdidas nuevas a las viejas. <strong>Antídoto:</strong> «si empezara hoy desde cero, ¿elegiría esto?»."},{"y":"7","icon":"📅","label":"Exceso de confianza","text":"Estimar con el <strong>mejor día imaginable</strong>. <strong>Gatillo:</strong> planificar sin datos. <strong>Por dentro:</strong> se olvidan los imprevistos que siempre ocurren. <strong>Antídoto:</strong> «¿cuánto tardó de verdad la última vez?»."},{"y":"8","icon":"🏆","label":"Superviviente","text":"Solo se ve a los que <strong>ganaron</strong>. <strong>Gatillo:</strong> un caso de éxito muy visible. <strong>Por dentro:</strong> los que fracasaron no publican su fracaso. <strong>Antídoto:</strong> «¿cuántos hicieron esto mismo y no funcionó?»."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🛡️</span><span class="ms-text"><strong>Pediste 24 horas:</strong> la presión se corta en seco y la conversación pasa del sentimiento a los números.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📄</span><span class="ms-text"><strong>Al día siguiente decides tú:</strong> si el plazo era real, la oferta sigue en pie y ahora con condiciones tuyas. Si se cayó, la presión era el producto.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">✍️</span><span class="ms-text"><strong>Contestaste en caliente:</strong> el sí salió con la emoción alta y sin comparar nada.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔗</span><span class="ms-text"><strong>Y la coherencia lo amarra:</strong> ese sí pequeño se cobra después con uno más grande. No fue tonto: fue una decisión tomada en el peor momento posible.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

