const parteData={"anclaje":{"nombre":"El anclaje","icon":"⚓","estructura":{"title":"Qué es","info":"• El <strong>primer número</strong> que se escucha fija el terreno<br>• Todo lo que viene después se mide como distancia a esa cifra<br>• Funciona igual con precios, plazos y porcentajes"},"funcion":{"title":"Cómo se dispara","info":"• Alguien dice una cifra antes que tú<br>• La conversación pasa de «cuánto vale» a <strong>«cuánto se baja»</strong><br>• El descuento conseguido se siente como una victoria propia"},"enfermedades":{"title":"Dónde se ve en el proyecto","info":"• El inversionista que abre con 200.000 y ofrece 80.000<br>• El patrocinador que dice cuánto suele pagar «en estos casos»<br>• La primera estimación de horas que alguien suelta en una reunión"},"cuidados":{"title":"El antídoto","info":"• Preguntar <strong>«¿de dónde salió esa cifra?»</strong><br>• Calcular el número propio en casa, antes de la reunión<br>• Decir en voz alta «ese número es tuyo» y sacar el propio"}},"confirmacion":{"nombre":"La confirmación","icon":"🔍","estructura":{"title":"Qué es","info":"• Se busca y se recuerda <strong>lo que encaja</strong> con lo que ya se creía<br>• Lo que contradice se mira por encima o se explica<br>• No es mala fe: es economía de esfuerzo"},"funcion":{"title":"Cómo se dispara","info":"• Basta con tener ya una opinión formada<br>• Se elige la fuente que va a decir que sí<br>• Se cuenta lo que confirma y se olvida contar lo demás"},"enfermedades":{"title":"Dónde se ve en el proyecto","info":"• Preguntar solo a las maestras que ya usan M.E.T.A.S<br>• Leer los comentarios buenos y saltarse los tibios<br>• Medir el éxito por las felicitaciones y no por el uso"},"cuidados":{"title":"El antídoto","info":"• <strong>«¿Qué dato me haría cambiar de opinión?»</strong><br>• Ir a buscar ese dato a propósito, aunque incomode<br>• Hablar con tres que lo dejaron: valen más que veinte que aplauden"}},"perdida":{"nombre":"La aversión a la pérdida","icon":"😰","estructura":{"title":"Qué es","info":"• Perder duele <strong>alrededor del doble</strong> de lo que alegra ganar lo mismo<br>• Por eso se prefiere no perder antes que ganar<br>• Es el motor de casi toda la urgencia comercial"},"funcion":{"title":"Cómo se dispara","info":"• Un plazo que vence<br>• La idea de que otro se lo va a llevar<br>• Cualquier frase con la forma <strong>«si no lo tomas ahora…»</strong>"},"enfermedades":{"title":"Dónde se ve en el proyecto","info":"• «El presupuesto se cierra el viernes»<br>• No soltar una función que nadie usa, por si acaso<br>• Aceptar un convenio flojo para no quedarse sin ninguno"},"cuidados":{"title":"El antídoto","info":"• <strong>«Si no tuviera fecha, ¿lo aceptaría igual?»</strong><br>• Pedir un día: casi todos los plazos resisten un día<br>• Si el plazo no resiste, dependía de que no lo pensaras"}},"hundido":{"nombre":"El costo hundido","icon":"🕳️","estructura":{"title":"Qué es","info":"• Seguir por <strong>lo ya invertido</strong> en vez de por lo que conviene<br>• Lo gastado no vuelve, se decida lo que se decida<br>• Cuanto más se lleva metido, más fuerte tira"},"funcion":{"title":"Cómo se dispara","info":"• Mucho tiempo, dinero o cariño puesto en algo<br>• La idea de «tirar a la basura» lo hecho<br>• Tener que explicarle a otro por qué se cambia de rumbo"},"enfermedades":{"title":"Dónde se ve en el proyecto","info":"• Las setecientas horas del motor de misiones<br>• Sostener una ruta que nadie de la casa está estudiando<br>• Mantener una herramienta propia solo porque costó hacerla"},"cuidados":{"title":"El antídoto","info":"• <strong>«Si empezara hoy desde cero, ¿elegiría esto?»</strong><br>• Listar las razones que NO dependen de lo gastado<br>• Si quedan razones buenas, se sigue; si no, se suelta y se anota la fecha"}}};
let labParte='centro',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🪞 ¡'+name+' completó la Etapa 1 de la Ruta de la Persuasión (Sesgos, los atajos que deciden por ti)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

// ===================== INIT =====================
window.addEventListener('DOMContentLoaded',()=>{
  initTheme();
  loadProgress();
  initTimeline();
  upFC();
  buildQz();
  showQz();
  buildClass();
  showId();
  showCmp();
  updateRetoButtons();
  buildRoute();
  showNeuron();
  showNeuro();
  showEnfer();
  updateLabDisplay();
  document.querySelector('[data-parte="web"]')?.classList.add('active-pri');
  document.querySelector('[data-aspecto="estructura"]')?.classList.add('active-sec');
  renderAchPanel();
});
